package com.sabyeguyz.clinic.treatment; import java.util.List; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; public interface TreatmentRepository extends JpaRepository<Treatment,Long>{List<Treatment> findByPatientIdOrderByCreatedAtDesc(Long patientId); Page<Treatment> findByPatientId(Long patientId,Pageable pageable);}
